#!/usr/bin/env python3
"""
forge_analysis_install.py  -  writes analysis.html (the standalone analysis page)
into the repo, byte-for-byte, and verifies the result.

New file, so no PRE hash. It refuses to OVERWRITE an existing analysis.html unless
you pass --force (so it can never clobber a hand-edited version by surprise).
NO workflow run needed - analysis.html is a hand-maintained page like the debrief.
"""
import gzip, base64, hashlib, os, sys

TARGET = "analysis.html"
EXPECT = "105b0cfa3fa0ade933c763e187252dc798fe470d0a6a0b291c04988a2e5b588c"
BLOB = ""

def main():
    if os.path.exists(TARGET) and "--force" not in sys.argv:
        print("ABORT: %s already exists. Re-run with --force to overwrite." % TARGET); sys.exit(1)
    data = gzip.decompress(base64.b64decode(BLOB))
    got = hashlib.sha256(data).hexdigest()
    if got != EXPECT:
        print("ABORT: payload checksum mismatch - refusing to write a corrupt file."); sys.exit(1)
    open(TARGET, "wb").write(data)
    back = hashlib.sha256(open(TARGET,"rb").read()).hexdigest()
    if back != EXPECT:
        print("ABORT: file on disk does not match after write."); sys.exit(1)
    print("OK  analysis.html written (%d bytes)." % len(data))
    print("    sha256:", EXPECT)
    print("\nNext: git pull --rebase ; git add analysis.html forge_analysis_install.py ; commit ; push. NO workflow run.")
    print("Then open: theseanman.github.io/forge-daily-brief/analysis.html")

if __name__ == "__main__":
    main()
